const mongoose = require("mongoose");

/* ── Counter billing ──────────────────────────────────────────────────────
 * One document per bill raised at the shop counter. This is the store behind
 * /api/billing and is independent of the ERP state blob (erp_sales): bills
 * are written one at a time, so two counters can never overwrite each other.
 *
 * `source` records how the bill came to exist:
 *   manual — a cashier rang it up on the New Bill screen
 *   auto   — generated by Auto Billing from a day's PhonePe/cash takings.
 *            The item mix on these is an estimate, not what was rung up.
 * ────────────────────────────────────────────────────────────────────────── */

const billLineSchema = new mongoose.Schema(
  {
    productId: { type: String, default: "" },
    // Billing category the line was sold under (empty for a custom line).
    categoryId: { type: String, default: "" },
    name: { type: String, required: true, trim: true },
    variant: { type: String, trim: true, default: "" },
    category: { type: String, trim: true, default: "" },
    hsnCode: { type: String, trim: true, default: "" },
    qty: { type: Number, required: true, min: 0 },
    unitPrice: { type: Number, required: true, min: 0 },
    gstRate: { type: Number, default: 0, min: 0 },
    lineTotal: { type: Number, required: true, min: 0 },
    taxableValue: { type: Number, default: 0 },
    cgst: { type: Number, default: 0 },
    sgst: { type: Number, default: 0 },
  },
  { _id: false },
);

const billPaymentSchema = new mongoose.Schema(
  {
    mode: {
      type: String,
      enum: ["cash", "phonepe", "card", "other"],
      required: true,
    },
    amount: { type: Number, required: true, min: 0 },
    reference: { type: String, trim: true, default: "" },
  },
  { _id: false },
);

const billingBillSchema = new mongoose.Schema(
  {
    billNo: { type: String, required: true, trim: true },
    // When the sale happened (for auto bills: the generated time on that day).
    billDate: { type: Date, required: true },
    // "YYYY-MM-DD" in IST — what every report groups and filters on.
    dateKey: { type: String, required: true },

    items: { type: [billLineSchema], default: [] },
    itemCount: { type: Number, default: 0 },

    subTotal: { type: Number, required: true, min: 0 },
    discount: { type: Number, default: 0, min: 0 },
    taxableTotal: { type: Number, default: 0 },
    cgstTotal: { type: Number, default: 0 },
    sgstTotal: { type: Number, default: 0 },
    grandTotal: { type: Number, required: true, min: 0 },

    payments: { type: [billPaymentSchema], default: [] },
    // cash | phonepe | card | other | split
    paymentMode: { type: String, default: "cash" },

    customerName: { type: String, trim: true, default: "" },
    customerPhone: { type: String, trim: true, default: "" },
    note: { type: String, trim: true, default: "" },

    source: { type: String, enum: ["manual", "auto"], default: "manual" },
    autoBatchId: { type: String, default: "" },

    status: { type: String, enum: ["active", "cancelled"], default: "active" },
    cancelReason: { type: String, trim: true, default: "" },
    cancelledAt: { type: Date },
    cancelledBy: { type: String, default: "" },

    createdById: { type: String, default: "" },
    createdByName: { type: String, default: "" },
  },
  { collection: "billing_bills", timestamps: true },
);

billingBillSchema.index({ billNo: 1 }, { unique: true });
billingBillSchema.index({ dateKey: 1, status: 1 });
billingBillSchema.index({ billDate: -1 });
billingBillSchema.index({ autoBatchId: 1 });

module.exports =
  mongoose.models.BillingBill || mongoose.model("BillingBill", billingBillSchema);
